import { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { getProgrammes } from "../../services/api";
import GroupsIcon from "@mui/icons-material/Groups";
import SettingsIcon from "@mui/icons-material/Settings";
import CameraAltIcon from "@mui/icons-material/CameraAlt";

function getAuthUser() {
    const raw = localStorage.getItem('authUser');
    if (!raw) return null;
    try { return JSON.parse(raw); } catch { return null; }
}

export default function StaffLandingPage() {
    const navigate = useNavigate();
    const currentUser = getAuthUser();

    if (!currentUser) {
        navigate('/login');
        return null;
    }

    const [programmes, setProgrammes] = useState([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        getProgrammes()
            .then(setProgrammes)
            .catch(() => {})
            .finally(() => setLoading(false));
    }, []);

    const activeProgrammes = programmes.filter(p => p.status === 'active');
    const totalDelegates = programmes.reduce((sum, p) => sum + (p.totalDelegates || 0), 0);
    const totalChecked = programmes.reduce((sum, p) => sum + (p.checkedIn || 0), 0);

    return (
        <main className="staff-page">
            <header className="staff-hero">
                <h1 className="staff-hero-name">Welcome, {currentUser.name}</h1>
                <p className="staff-hero-sub">Manage your programmes, check in delegates, and monitor attendance.</p>
            </header>

            {!loading && programmes.length > 0 && (
                <div className="staff-stats">
                    <div className="staff-stat-card">
                        <p className="staff-stat-value">{activeProgrammes.length}</p>
                        <p className="staff-stat-label">Active programmes</p>
                    </div>
                    <div className="staff-stat-card">
                        <p className="staff-stat-value">{totalChecked}/{totalDelegates}</p>
                        <p className="staff-stat-label">Total check-ins</p>
                    </div>
                </div>
            )}

            {loading && (
                <div className="staff-stats">
                    <div className="staff-stat-card py-6">
                        <p className="text-xs text-slate-400">Loading...</p>
                    </div>
                    <div className="staff-stat-card py-6">
                        <p className="text-xs text-slate-400">Loading...</p>
                    </div>
                </div>
            )}

            <div className="staff-actions">
                <p className="section-title">Quick Actions</p>
                <button className="staff-action-row" onClick={() => navigate("/dashboard")}>
                    <div className="staff-action-icon bg-sky-100 text-sky-600"><GroupsIcon className="icon-md" /></div>
                    <div><p className="text-sm font-medium text-slate-800">Dashboard</p><p className="text-xs text-slate-400">View live attendance</p></div>
                </button>
                <button className="staff-action-row" onClick={() => navigate("/programmes")}>
                    <div className="staff-action-icon bg-emerald-100 text-emerald-600"><SettingsIcon className="icon-md" /></div>
                    <div><p className="text-sm font-medium text-slate-800">Manage Programmes</p><p className="text-xs text-slate-400">Create and edit programmes</p></div>
                </button>
                <button className="staff-action-row" onClick={() => navigate("/camera")}>
                    <div className="staff-action-icon bg-amber-100 text-amber-600"><CameraAltIcon className="icon-md" /></div>
                    <div><p className="text-sm font-medium text-slate-800">Camera</p><p className="text-xs text-slate-400">Face recognition & QR check-in</p></div>
                </button>
            </div>
        </main>
    );
}

import { QRCodeCanvas } from 'qrcode.react';
import { useNavigate } from 'react-router-dom';

function getAuthUser() {
    const raw = localStorage.getItem('authUser');
    if (!raw) return null;
    try {
        return JSON.parse(raw);
    } catch {
        return null;
    }
}

export default function BadgePage() {
    const navigate = useNavigate();
    const currentUser = getAuthUser();

    if (!currentUser) {
        navigate('/login');
        return null;
    }

    return (
        <main className="badge-page">
            <header className="page-header">
                <h1 className="page-title">Welcome, {currentUser.name}</h1>
            </header>

            <div className="page-content">
                <p className="text-sm text-slate-500">Your digital badge for check-in. Show the QR code below to staff at any checkpoint.</p>

                <div className="badge-card">
                    <div className="badge-qr-wrap">
                        <QRCodeCanvas
                            value={currentUser.id}
                            size={200}
                            bgColor="#ffffff"
                            fgColor="#0f172a"
                            level="M"
                        />
                    </div>

                    <div className="text-center">
                        <p className="text-base font-semibold text-slate-800">{currentUser.name}</p>
                        <p className="text-xs text-slate-400 mt-0.5">{currentUser.email}</p>
                    </div>

                    <div className="badge-id">
                        {currentUser.id}
                    </div>
                </div>

                <p className="text-xs text-slate-400 text-center max-w-[280px] mx-auto">
                    Show this QR code to staff to check in. The code encodes your account UUID.
                </p>
            </div>
        </main>
    );
}

import { useRef, useEffect, useState, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import KeyboardArrowDown from '@mui/icons-material/KeyboardArrowDown';
import CheckIcon from '@mui/icons-material/Check';
import UndoIcon from '@mui/icons-material/Undo';
import { getProgrammes, recognizeFaces, markAttendanceBatch, lookupByBadge } from '../../services/api';
import QrScanner from '../../components/qr_scanner/QrScanner';
import { useConnectivity } from '../../hooks/useConnectivity';

const MODEL_URL = 'https://cdn.jsdelivr.net/gh/justadudewhohacks/face-api.js@0.22.2/weights/';
const DETECTION_FRAME_SKIP = 8;

function getAuthUser() {
    const raw = localStorage.getItem('authUser');
    if (!raw) return null;
    try {
        return JSON.parse(raw);
    } catch {
        return null;
    }
}

export default function CameraPage() {
    const navigate = useNavigate();
    const currentUser = getAuthUser();

    if (!currentUser) {
        navigate('/login');
        return null;
    }
    if (currentUser.role !== 'staff') {
        navigate('/');
        return null;
    }

    const videoRef = useRef(null);
    const canvasRef = useRef(null);
    const displaySizeRef = useRef(null);
    const rafRef = useRef(null);
    const cancelledRef = useRef(false);
    const frameCountRef = useRef(0);
    const scanKeyRef = useRef(0);

    const { isOnline } = useConnectivity();

    const [programmes, setProgrammes] = useState([]);
    const [programmeId, setProgrammeId] = useState(null);
    const [showPicker, setShowPicker] = useState(false);

    const [error, setError] = useState(null);
    const [status, setStatus] = useState('Loading face detection models...');
    const [facingMode, setFacingMode] = useState('user');
    const [captured, setCaptured] = useState(false);
    const [capturedImage, setCapturedImage] = useState(null);
    const [recognizing, setRecognizing] = useState(false);
    const [matches, setMatches] = useState([]);
    const [selected, setSelected] = useState(new Set());
    const [confirming, setConfirming] = useState(false);
    const [done, setDone] = useState(false);
    const [mode, setMode] = useState('facial');

    useEffect(() => {
        getProgrammes()
            .then((list) => {
                setProgrammes(list);
                if (list.length > 0) setProgrammeId(list[0].id);
            })
            .catch((e) => setError(e.message));
    }, []);

    const stopStream = useCallback(() => {
        if (rafRef.current) cancelAnimationFrame(rafRef.current);
        if (videoRef.current?.srcObject) {
            videoRef.current.srcObject.getTracks().forEach((t) => t.stop());
            videoRef.current.srcObject = null;
        }
    }, []);

    const startCamera = useCallback(async (mode) => {
        try {
            await Promise.all([
                faceapi.nets.ssdMobilenetv1.loadFromUri(MODEL_URL),
            ]);
            if (cancelledRef.current) return;
            setStatus('Starting camera...');

            if (!navigator.mediaDevices?.getUserMedia) {
                throw new Error('Camera access requires HTTPS. Access this page via HTTPS or localhost.');
            }
            const stream = await navigator.mediaDevices.getUserMedia({
                video: { facingMode: mode },
            });
            if (cancelledRef.current) return;
            const video = videoRef.current;
            if (!video) return;
            video.srcObject = stream;

            await new Promise((resolve) => {
                video.addEventListener('loadedmetadata', resolve, { once: true });
            });

            if (cancelledRef.current) return;
            try {
                await video.play();
            } catch (playErr) {
                if (!cancelledRef.current) setError(playErr.message);
                return;
            }

            const { videoWidth, videoHeight } = video;
            const canvas = canvasRef.current;
            const renderedWidth = video.offsetWidth || videoWidth;
            const renderedHeight = video.offsetHeight || videoHeight;
            const displaySize = { width: renderedWidth, height: renderedHeight };
            displaySizeRef.current = displaySize;

            faceapi.matchDimensions(canvas, displaySize);

            setStatus('Detecting faces...');
            detectLoop();
        } catch (err) {
            if (!cancelledRef.current) setError(err.message);
        }
    }, []);

    useEffect(() => {
        cancelledRef.current = false;
        setCaptured(false);
        setCapturedImage(null);
        setMatches([]);
        setSelected(new Set());
        setConfirming(false);
        setDone(false);
        stopStream();
        if (mode === 'facial') {
            startCamera(facingMode);
        }

        return () => {
            cancelledRef.current = true;
            stopStream();
        };
    }, [facingMode, startCamera, stopStream, programmeId, mode]);

    function detectLoop() {
        if (cancelledRef.current) return;
        const video = videoRef.current;
        const canvas = canvasRef.current;
        if (!video || !canvas || video.readyState < 2) {
            rafRef.current = requestAnimationFrame(detectLoop);
            return;
        }

        frameCountRef.current += 1;
        if (frameCountRef.current % DETECTION_FRAME_SKIP !== 0) {
            rafRef.current = requestAnimationFrame(detectLoop);
            return;
        }

        faceapi
            .detectAllFaces(video, new faceapi.SsdMobilenetv1Options({ minConfidence: 0.5 }))
            .then((detections) => {
                const ctx = canvas.getContext('2d');
                ctx.clearRect(0, 0, canvas.width, canvas.height);

                const displaySize = displaySizeRef.current;
                const resized = faceapi.resizeResults(detections, displaySize);

                if (facingMode === 'user') {
                    ctx.save();
                    ctx.translate(canvas.width, 0);
                    ctx.scale(-1, 1);
                }

                resized.forEach((d) => {
                    const box = d.box;
                    ctx.strokeStyle = '#00ff00';
                    ctx.lineWidth = 4;
                    ctx.strokeRect(box.x, box.y, box.width, box.height);
                });

                if (facingMode === 'user') {
                    ctx.restore();
                }

                rafRef.current = requestAnimationFrame(detectLoop);
            })
            .catch((err) => {
                if (!cancelledRef.current) setError(err.message);
            });
    }

    function toggleCamera() {
        setFacingMode((prev) => (prev === 'user' ? 'environment' : 'user'));
    }

    async function handleCapture() {
        if (!programmeId) {
            setError('Please select a programme first');
            return;
        }

        const video = videoRef.current;
        const canvas = document.createElement('canvas');
        canvas.width = video.videoWidth;
        canvas.height = video.videoHeight;

        if (facingMode === 'user') {
            const ctx = canvas.getContext('2d');
            ctx.save();
            ctx.translate(canvas.width, 0);
            ctx.scale(-1, 1);
            ctx.drawImage(video, 0, 0);
            ctx.restore();
        } else {
            canvas.getContext('2d').drawImage(video, 0, 0);
        }

        cancelledRef.current = true;
        stopStream();

        const imageBase64 = canvas.toDataURL('image/jpeg', 0.8).split(',')[1];
        setCapturedImage(imageBase64);
        setCaptured(true);
        setRecognizing(true);

        try {
            const result = await recognizeFaces(programmeId, imageBase64);
            setMatches(result.matches);
            setSelected(new Set(result.matches.map((m) => m.delegateId)));
        } catch (e) {
            setError(e.message);
        } finally {
            setRecognizing(false);
        }
    }

    function toggleMatch(delegateId) {
        setSelected((prev) => {
            const next = new Set(prev);
            if (next.has(delegateId)) next.delete(delegateId);
            else next.add(delegateId);
            return next;
        });
    }

    async function handleConfirm() {
        if (selected.size === 0 || !programmeId) return;
        setConfirming(true);
        try {
            const records = Array.from(selected).map((delegateId) => ({
                delegateId,
                status: 'present',
                method: mode === 'qr' ? 'qr' : 'auto',
            }));
            await markAttendanceBatch(programmeId, records);
            setDone(true);
        } catch (e) {
            setError(e.message);
        } finally {
            setConfirming(false);
        }
    }

    function handleRetake() {
        cancelledRef.current = false;
        setCaptured(false);
        setCapturedImage(null);
        setMatches([]);
        setSelected(new Set());
        setConfirming(false);
        setDone(false);
        setError(null);
        scanKeyRef.current += 1;
        if (mode === 'facial') {
            startCamera(facingMode);
        }
    }

    const currentProgramme = programmes.find((p) => p.id === programmeId);

    async function handleQrScan(decodedText) {
        if (!programmeId) return;
        setRecognizing(true);
        setCaptured(true);
        setStatus('Looking up badge...');
        try {
            const result = await lookupByBadge(programmeId, decodedText);
            setMatches(result.matches.map((m) => ({
                delegateId: m.delegateId,
                name: m.name,
                confidence: null,
                imageData: null,
            })));
            setSelected(new Set(result.matches.map((m) => m.delegateId)));
            if (result.errors.length > 0) {
                setError(result.errors.join('; '));
            }
        } catch (e) {
            setError(e.message);
        } finally {
            setRecognizing(false);
        }
    }

    function handleModeChange(newMode) {
        if (newMode === mode) return;
        cancelledRef.current = true;
        stopStream();
        setCaptured(false);
        setCapturedImage(null);
        setMatches([]);
        setSelected(new Set());
        setConfirming(false);
        setDone(false);
        setError(null);
        cancelledRef.current = false;
        setMode(newMode);
    }

    return (
        <main className="camera-page">
            <header className="camera-header">
                <h1 className="camera-title">{mode === 'facial' ? 'Facial Recognition' : 'QR Code Scanner'}</h1>
                <div className="relative">
                    <button
                        className="camera-picker-btn"
                        onClick={() => setShowPicker((p) => !p)}
                    >
                        {currentProgramme?.name || 'Select'}
                        <KeyboardArrowDown className="icon-xs" />
                    </button>
                    {showPicker && (
                        <div className="absolute top-full left-0 mt-1 z-20 min-w-[180px] rounded-xl border border-slate-100 bg-white p-1 shadow-lg">
                            {programmes.map((p) => (
                                <button
                                    key={p.id}
                                    className={`block w-full cursor-pointer rounded-lg px-3 py-2 text-left text-xs font-medium transition-colors ${
                                        p.id === programmeId ? 'bg-sky-50 text-sky-700' : 'text-slate-700 hover:bg-slate-50'
                                    }`}
                                    onClick={() => { setProgrammeId(p.id); setShowPicker(false); }}
                                >
                                    {p.name}
                                </button>
                            ))}
                        </div>
                    )}
                </div>
            </header>

            {error && (
                <div className="error-banner">
                    <span>{error}</span>
                    <button className="cursor-pointer underline" onClick={() => setError(null)}>Dismiss</button>
                </div>
            )}

            <div className="segmented mx-auto mt-4 w-full max-w-[260px]">
                <button
                    className={`segmented-btn ${mode === 'facial' ? 'segmented-btn-active' : ''}`}
                    onClick={() => handleModeChange('facial')}
                >
                    Face Recognition
                </button>
                <button
                    className={`segmented-btn ${mode === 'qr' ? 'segmented-btn-active' : ''}`}
                    onClick={() => handleModeChange('qr')}
                >
                    QR Code
                </button>
            </div>

            {!captured ? (
                <>
                    {mode === 'facial' && (
                        <div className="camera-status">
                            {status !== 'Detecting faces...' && (
                                <span>{status}</span>
                            )}
                        </div>
                    )}

                    {mode === 'qr' && (
                        <p className="camera-status">Point camera at a QR code</p>
                    )}

                    <div className="px-4">
                        <div className="camera-frame">
                            {mode === 'facial' && (
                                <>
                                    <video
                                        ref={videoRef}
                                        autoPlay
                                        muted
                                        playsInline
                                        className={`camera-video ${facingMode === 'user' ? '-scale-x-100' : ''}`}
                                    />
                                    <canvas
                                        ref={canvasRef}
                                        className="camera-canvas"
                                    />
                                </>
                            )}
                            {mode === 'qr' && (
                                <QrScanner
                                    key={scanKeyRef.current}
                                    onScan={handleQrScan}
                                    onError={(msg) => setError(msg)}
                                    facingMode={facingMode}
                                />
                            )}
                        </div>
                    </div>

                    <div className="camera-actions">
                        {mode === 'facial' && (
                            <button
                                className={`btn ${programmeId && isOnline ? 'btn-primary' : 'btn-ghost'}`}
                                disabled={!programmeId || !isOnline}
                                onClick={handleCapture}
                            >
                                {isOnline ? 'Capture & Recognize' : 'Unavailable while offline'}
                            </button>
                        )}
                        <button
                            className="btn btn-ghost"
                            onClick={toggleCamera}
                        >
                            Switch to {facingMode === 'user' ? 'Back' : 'Front'}
                        </button>
                    </div>
                </>
            ) : (
                <div className="px-4 pb-6">
                    {recognizing ? (
                        <div className="flex flex-col items-center gap-3 pt-8">
                            <div className="spinner" />
                            <p className="text-sm text-slate-400">{mode === 'facial' ? 'Recognizing faces...' : 'Looking up badge...'}</p>
                        </div>
                    ) : done ? (
                        <div className="flex flex-col items-center gap-4 pt-8">
                            <div className="flex h-14 w-14 items-center justify-center rounded-full bg-emerald-100">
                                <CheckIcon className="icon-lg text-emerald-600" />
                            </div>
                            <p className="text-base font-semibold text-white">Attendance marked</p>
                            <p className="text-sm text-slate-400">{selected.size} delegate(s) checked in</p>
                            <button
                                className="btn btn-primary"
                                onClick={handleRetake}
                            >
                                Scan Again
                            </button>
                        </div>
                    ) : (
                        <>
                            <p className="camera-result-title mx-auto max-w-[480px]">
                                Matches ({matches.length})
                            </p>

                            {matches.length === 0 ? (
                                <div className="empty-state">
                                    <p className="text-sm text-slate-400">No matching delegates found</p>
                                    <button
                                        className="btn btn-primary"
                                        onClick={handleRetake}
                                    >
                                        Try Again
                                    </button>
                                </div>
                            ) : (
                                <>
                                    <div className="camera-match-list">
                                        {matches.map((m) => {
                                            const isSelected = selected.has(m.delegateId);
                                            return (
                                                <div
                                                    key={m.delegateId}
                                                    className={`check-row border border-slate-200/80 bg-white ${isSelected ? 'check-row-checked' : ''}`}
                                                    onClick={() => toggleMatch(m.delegateId)}
                                                >
                                                    <div className="flex flex-1 items-center gap-3">
                                                        {m.imageData ? (
                                                            <img
                                                                src={`data:image/jpeg;base64,${m.imageData}`}
                                                                alt={m.name}
                                                                className="h-8 w-8 rounded-full object-cover"
                                                            />
                                                        ) : (
                                                            <div className={`avatar avatar-sm ${isSelected ? 'bg-sky-600 text-white' : 'avatar-soft'}`}>
                                                                {m.name.charAt(0)}
                                                            </div>
                                                        )}
                                                        <div>
                                                            <p className="text-sm font-medium text-slate-800">{m.name}</p>
                                                            {m.confidence !== null && (
                                                                <p className="text-xs text-slate-400">
                                                                    Confidence: {Math.round(m.confidence * 100)}%
                                                                </p>
                                                            )}
                                                        </div>
                                                    </div>
                                                    <div className={`flex h-5 w-5 shrink-0 items-center justify-center rounded border-2 transition-colors ${
                                                        isSelected ? 'border-sky-600 bg-sky-600' : 'border-slate-300'
                                                    }`}>
                                                        {isSelected && <CheckIcon className="icon-xs text-white" />}
                                                    </div>
                                                </div>
                                            );
                                        })}
                                    </div>

                                    <div className="mx-auto flex max-w-[480px] gap-2 px-4">
                                        <button
                                            className={`btn flex-1 ${selected.size === 0 || !isOnline ? 'btn-ghost' : 'btn-primary'}`}
                                            disabled={selected.size === 0 || confirming || !isOnline}
                                            onClick={handleConfirm}
                                        >
                                            {confirming ? 'Marking...' : !isOnline ? 'Unavailable while offline' : `Confirm (${selected.size})`}
                                        </button>
                                        <button
                                            className="btn btn-ghost px-4"
                                            onClick={handleRetake}
                                        >
                                            <UndoIcon className="icon-sm" />
                                        </button>
                                    </div>
                                </>
                            )}
                        </>
                    )}
                </div>
            )}
        </main>
    );
}
